sys_script.script:
/**
 * Business Rule script for Service Event (after insert).
 *
 * - If Event Type = Down and no open incident exists for the CI,
 *   creates a new incident linked to that CI and stores the incident
 *   reference back on the event record.
 *
 * - If Event Type = Up and an open auto-created incident exists for
 *   the CI, resolves that incident with a resolution note.
 */
(function () {
    var eventType = current.getValue('event_type');
    var ciRef = current.getValue('ci_reference');

    if (!ciRef) {
        gs.debug('[ITOM Health] Skipping event - no CI reference set.');
        return;
    }

    if (eventType === 'down') {
        handleDownEvent();
    } else if (eventType === 'up') {
        handleUpEvent();
    }

    function handleDownEvent() {
        // Check for existing open incident linked to this CI created by automation
        var existing = new GlideRecord('incident');
        existing.addQuery('cmdb_ci', ciRef);
        existing.addQuery('state', '!=', '7');
        existing.addQuery('state', '!=', '6');
        existing.addQuery('short_description', 'STARTSWITH', '[ITOM Auto]');
        existing.query();

        if (existing.hasNext()) {
            gs.debug('[ITOM Health] Open incident already exists for CI ' + ciRef + '. Skipping creation.');
            return;
        }

        // Map event severity to incident impact/urgency
        var severity = current.getValue('severity');
        var impactMap = {
            critical: '1',
            major: '2',
            minor: '3',
            warning: '3',
            info: '3'
        };
        var urgencyMap = {
            critical: '1',
            major: '2',
            minor: '2',
            warning: '3',
            info: '3'
        };

        var impact = impactMap[severity] || '3';
        var urgency = urgencyMap[severity] || '3';

        // Create new incident
        var inc = new GlideRecord('incident');
        inc.initialize();
        inc.setValue('short_description', '[ITOM Auto] Service Down - CI ' + ciRef);
        inc.setValue('description',
            'Auto-created by ITOM Infrastructure Health Tracker.\n' +
            'Event Source: ' + current.getValue('event_source') + '\n' +
            'Severity: ' + severity + '\n' +
            'Timestamp: ' + current.getValue('timestamp'));
        inc.setValue('cmdb_ci', ciRef);
        inc.setValue('impact', impact);
        inc.setValue('urgency', urgency);
        inc.setValue('category', 'software');
        var incSysId = inc.insert();

        if (incSysId) {
            gs.info('[ITOM Health] Created incident ' + incSysId + ' for CI ' + ciRef);

            // Store the incident reference back on the event record
            current.setValue('correlated_incident', incSysId);
            current.update();
        }
    }

    function handleUpEvent() {
        var inc = new GlideRecord('incident');
        inc.addQuery('cmdb_ci', ciRef);
        inc.addQuery('state', '!=', '7');
        inc.addQuery('state', '!=', '6');
        inc.addQuery('short_description', 'STARTSWITH', '[ITOM Auto]');
        inc.query();

        while (inc.next()) {
            inc.setValue('state', '6');
            inc.setValue('close_code', 'Solved (Permanently)');
            inc.setValue('close_notes',
                'Auto-resolved by ITOM Infrastructure Health Tracker. ' +
                'Service Up event received for CI ' + ciRef + '.');
            inc.update();
            gs.info('[ITOM Health] Auto-resolved incident ' + inc.getUniqueValue() + ' for CI ' + ciRef);
        }
    }
})();
